import (
	"os/exec"
	"path/filepath"
	"strings"
	"testing"
)

// 화면 로직의 상당 부분은 Go 가 아니라 test/js/*.test.mjs 로 검증합니다.
// 그런데 그 파일들을 실행하는 곳이 아무 데도 없었습니다 — CI 도, go test 도.
// 아무도 돌리지 않는 검증은 조용히 썩습니다. 여기서 묶어 두면 `go test ./...`
// 한 번으로 같이 돌고, 세 CI 작업 모두가 이미 그것을 실행합니다.
func TestBrowserModuleTests(t *testing.T) {
	if _, err := exec.LookPath("node"); err != nil {
		t.Skip("node 없음")
	}
	root, err := filepath.Abs("../..")
	if err != nil {
		t.Fatal(err)
	}
	files, err := filepath.Glob(filepath.Join(root, "test", "js", "*.test.mjs"))
	if err != nil {
		t.Fatal(err)
	}
	// 하나도 못 찾으면 경로가 어긋난 것입니다. 조용히 통과시키면 안 됩니다.
	if len(files) == 0 {
		t.Fatal("test/js/*.test.mjs 를 찾지 못했습니다")
	}
	for _, file := range files {
		name := filepath.Base(file)
		t.Run(name, func(t *testing.T) {
			t.Parallel()
			out, err := exec.Command("node", file).CombinedOutput()
			if err != nil {
				// node 의 출력을 함께 남깁니다. 없으면 "exit status 1" 만 보입니다.
				t.Fatalf("%v\n%s", err, strings.TrimSpace(string(out)))
			}
		})
	}
}
